import sys

def encode(s: str) -> str:
    return ''.join(
        chr((ord(ch) - ord('a') + 5) % 26 + ord('a')) if 'a' <= ch <= 'z' else ch
        for ch in s
    )

def decode(s: str) -> str:
    return ''.join(
        chr((ord(ch) - ord('a') - 5) % 26 + ord('a')) if 'a' <= ch <= 'z' else ch
        for ch in s
    )

def main():
    if len(sys.argv) > 1:
        op = sys.argv[1]
        text = ' '.join(sys.argv[2:]) if len(sys.argv) > 2 else ''
        if op == 'encode':
            print(encode(text))
        elif op == 'decode':
            print(decode(text))
        else:
            print("Usage: script.py <encode|decode> [text]")
    else:
        # If no args, read a line from stdin
        try:
            line = input()
        except EOFError:
            line = ''
        print(encode(line))

if __name__ == "__main__":
    main()

