def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    # Check divisibility up to the square root
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def process_sentence(sentence):
    """Process a sentence by retaining only words with prime character lengths."""
    return ' '.join(
        filter(lambda w: is_prime(len(w)), sentence.split())
    )
