def calculate_remaining_fruits(initial_fruits, eaten_fruits):
    """
    Calculate the remaining fruits count after eating some.

    Args:
        initial_fruits (dict): Dictionary mapping fruit names to their initial counts.
        eaten_fruits (dict): Dictionary mapping fruit names to the counts eaten.

    Returns:
        dict: Dictionary with remaining fruit counts.
    """
    return {
        fruit: initial_fruits.get(fruit, 0) - eaten_fruits.get(fruit, 0)
        for fruit in set(initial_fruits) | set(eaten_fruits)
    }

