def count_multiples_with_7(n: int) -> int:
    """
    Counts numbers under n that are multiples of 11 or 13 and contain the digit 7.
    """
    def has_seven(num: int) -> bool:
        """Check if a number contains the digit 7."""
        while num > 0:
            if num % 10 == 7:
                return True
            num //= 10
        return False

    return sum(
        1 for x in range(1, n)
        if (x % 11 == 0 or x % 13 == 0) and has_seven(x)
    )

